hudson.tasks.Shell.command:
echo "oc-"$(date "+%m-%d")"_${VersionName}_test_${BUILDS_TODAY}"

SubDir=release/android
PackageDir=/Volumes/ssd/Packages/${SubDir}
mkdir -p ${PackageDir}
VersionNum=(${VersionName//./ }) 
VersionCode=${VersionNum[2]}
changeMsg="Git分支:${GIT_BRANCH}
Hash:${GIT_COMMIT}"

if [ "${BuildPatch}" == "true" ];then
echo "BuildTarget:13\nVersionName:"${VersionName}"\nIl2CPP:true\nObb:false\nKeyaliasName:oc\nKeyaliasPass:skyunion\nBuildBundle:true\nResetBundleGroup:true\nARMv7:true\nARM64:true\ntargetSdkVersion:30\nHotFixMode:ILRT\nLogoTime:4" > ${WORKSPACE}/BuildConfig
/Applications/Unity/Unity.app/Contents/MacOS/Unity -projectPath ${WORKSPACE} -quit -batchmode -executeMethod Skyunion.BuildMenuItem.BuildPackageByConfig -logFile ${WORKSPACE}/Build.log
PackageName="oc_"$(date "+%m_%d")"_V${VersionName}_ilrt"
OldFile=${PackageDir}/${BasePackage}
NewFile="${PackageDir}/${PackageName}.apk"
mkdir -p ${PackageDir}/${VersionName}
PatchFile="${PackageDir}/${VersionName}/${PatchNumber}.zip"
mv ${WORKSPACE}"/../Packages/Android/Origin of Conquerors"${VersionCode}".apk" "${PackageDir}/${PackageName}.apk"
TempDir="${PackageDir}/temp"
mkdir -p ${TempDir}

echo "SubDir:assets\nTemp:${TempDir}\nOldFile:${OldFile}\nNewFile:${NewFile}\nPatchFile:${PatchFile}" > ${WORKSPACE}/BuildPatch
/Applications/Unity/Unity.app/Contents/MacOS/Unity -projectPath ${WORKSPACE} -quit -batchmode -executeMethod Skyunion.BuildMenuItem.BuildPatch -logFile ${WORKSPACE}/Build.log

changeMsg="${changeMsg}
旧包:http://10.15.122.36:8088/viewfile/${BasePackage}?path=/${SubDir}/${BasePackage}"
changeMsg="${changeMsg}
新包:http://10.15.122.36:8088/viewfile/${PackageName}.apk?path=/${SubDir}/${PackageName}.apk"
changeMsg="${changeMsg}
补丁文件:http://10.15.122.36:8088/viewfile/${PatchNumber}.zip?path=/${SubDir}/${VersionName}/${PatchNumber}.zip"
changeMsg="${changeMsg}
所有文件:http://10.15.122.36:8088/share#/${SubDir}"
curl -d "token=d32d3affa842ec468799037636b22dac&target=group&room=10001307&title=补丁打包完成&content_type=1&content=${changeMsg}&at_user=zhongyanghuang" http://im-api.skyunion.net/msg

else
PackageName="oc_"$(date "+%m_%d")"_V${VersionName}_full"
QaPackageName="oc_"$(date "+%m_%d")"_V${VersionName}_test${BUILDS_TODAY}"

echo "BuildTarget:13\nVersionName:"${VersionName}"\nIl2CPP:true\nObb:false\nKeyaliasName:oc\nKeyaliasPass:skyunion\nBuildBundle:true\nResetBundleGroup:true\nARMv7:true\nARM64:true\ntargetSdkVersion:30\nHotFixMode:NativeCode\n""LogoTime:4" > ${WORKSPACE}/BuildConfig
/Applications/Unity/Unity.app/Contents/MacOS/Unity -projectPath ${WORKSPACE} -quit -batchmode -executeMethod Skyunion.BuildMenuItem.BuildPackageByConfig -logFile ${WORKSPACE}/Build.log

mv ${WORKSPACE}"/../Packages/Android/Origin of Conquerors"${VersionCode}".apk" "${PackageDir}/${PackageName}.apk"

changeMsg="${changeMsg}
整包:http://10.15.122.36:8088/viewfile/${PackageName}.apk?path=/${SubDir}/${PackageName}.apk"
changeMsg="${changeMsg}
QA测试包:http://10.15.122.36:8088/viewfile/${QaPackageName}.apk?path=/${SubDir}/${PackageName}.apk"

PackageName="oc_"$(date "+%m_%d")"_V${VersionName}_obb"
SymbolName="${PackageName}-${BUILD_NUMBER}-symbol.zip"

echo "BuildTarget:13\nVersionName:"${VersionName}"\nIl2CPP:true\nObb:true\nKeyaliasName:oc\nKeyaliasPass:skyunion\nBuildBundle:false\nResetBundleGroup:false\nARMv7:true\nARM64:true\ntargetSdkVersion:30\nHotFixMode:NativeCode\nLogoTime:4\nSymbol:true" > ${WORKSPACE}/BuildConfig
/Applications/Unity/Unity.app/Contents/MacOS/Unity -projectPath ${WORKSPACE} -quit -batchmode -executeMethod Skyunion.BuildMenuItem.BuildPackageByConfig -logFile ${WORKSPACE}/Build.log

mv ${WORKSPACE}"/../Packages/Android/Origin of Conquerors"${VersionCode}".apk" "${PackageDir}/${PackageName}.apk"
cp -f ${WORKSPACE}"/../Packages/Android/Origin of Conquerors"${VersionCode}".main.obb" "${PackageDir}/${PackageName}.obb"
ObbName="main.${VersionCode}.com.igg.android.originofconquerors.obb"
mv ${WORKSPACE}"/../Packages/Android/Origin of Conquerors"${VersionCode}".main.obb" ${PackageDir}/${ObbName}
mv ${WORKSPACE}"/../Packages/Android/Origin of Conquerors"${VersionCode}-${VersionName}"-v${VersionCode}.symbols.zip" "${PackageDir}/${SymbolName}"

changeMsg="${changeMsg}
商店包:http://10.15.122.36:8088/viewfile/${PackageName}.apk?path=/${SubDir}/${PackageName}.apk"
changeMsg="${changeMsg}
上传用obb:http://10.15.122.36:8088/viewfile/${PackageName}.obb?path=/${SubDir}/${PackageName}.obb"
changeMsg="${changeMsg}
安装用obb:http://10.15.122.36:8088/viewfile/${ObbName}?path=/${SubDir}/${ObbName}"
changeMsg="${changeMsg}
符号文件:http://10.15.122.36:8088/viewfile/${SymbolName}?path=/${SubDir}/${SymbolName}"
changeMsg="${changeMsg}
所有文件:http://10.15.122.36:8088/share#/${SubDir}"

curl -d "token=d32d3affa842ec468799037636b22dac&target=group&room=10001307&title=商店包打包完成&content_type=1&content=${changeMsg}&at_user=zhongyanghuang" http://im-api.skyunion.net/msg
fi
